"use client";
import React, { useState } from "react";
import axios from "axios";
import { useRouter } from "next/navigation";
import Sidebar from "../../components/sidebar";
import Navbar from "../../components/Navbar";

const Addnewuser = () => {
  const [inputs, setInputs] = useState({
    idEtudiant:"",
    nom: "",
    prenom: "",
    email: "",
    motDePasse: "",
    annee: "",
    classe: "",
    filiere: "",
  });

  const [error, setError] = useState("");
  const router = useRouter();

  const handleChange = (event) => {
    const { name, value } = event.target;
    setInputs((prevValues) => ({ ...prevValues, [name]: value }));
  };

  const handleSubmit = async (event) => {
    event.preventDefault();
    setError("");

    if (Object.values(inputs).some((value) => value.trim() === "")) {
      setError("Tous les champs doivent être remplis.");
      return;
    }

    try {
      await axios.post("http://localhost:5000/api/addetudiant", inputs);
      router.push("/users/readEtu");
    } catch (err) {
      console.error("Erreur lors de l'ajout de l'étudiant:", err);
      setError("Impossible d'ajouter l'étudiant. Vérifiez votre connexion.");
    }
  };

  return (
    <div className="flex h-screen w-screen bg-white-100">
      {/* Barre latérale */}
      <Sidebar className="h-screen" />

      <div className="w-full flex flex-col h-screen">
        {/* Barre de navigation */}
        <Navbar />

        {/* Contenu principal */}
        <div className="w-full flex-1 py-5 flex flex-col items-center overflow-auto">
          <div className="bg-white shadow-lg rounded-xl p-8 w-full max-w-lg">
            {/* Bouton de retour */}
            <button 
              onClick={() => router.push("/users/readEtu")}
              className="mb-5 flex items-center text-blue-600 hover:text-blue-800 transition"
            >
              ← Retour à la gestion des Étudiants
            </button>

            {/* Titre */}
            <h1 className="text-2xl font-bold text-center text-gray-800 mb-6">
              Ajouter un Étudiant
            </h1>

            {/* Formulaire */}
            <form onSubmit={handleSubmit} className="space-y-1">
              {["idEtudiant","nom", "prenom", "email", "motDePasse", "annee", "classe", "filiere"].map((field, index) => (
                <div key={index}>
                  <label htmlFor={field} className="block text-sm font-medium text-gray-700">
                    {field.charAt(0).toUpperCase() + field.slice(1)}
                  </label>
                  <input 
                    type={
                      field === "email" ? "email" : 
                      field === "motDePasse" ? "password" : 
                      field === "annee" ? "number" : 
                      "text"
                    }
                    name={field} 
                    id={field} 
                    className="w-full px-4 py-2 mt-2 border border-blue-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none shadow-sm transition"
                    placeholder={`${field.charAt(0).toUpperCase() + field.slice(1)}...`} 
                    onChange={handleChange} 
                  />
                </div>
              ))}

              {/* Message d'erreur */}
              {error && <p className="text-red-500 text-sm mt-2">{error}</p>}

              {/* Bouton Ajouter */}
              <button 
                type="submit" 
                disabled={Object.values(inputs).some((value) => value.trim() === "")} 
                className="w-full bg-blue-500 text-white font-semibold py-2 px-4 rounded-lg shadow-md hover:bg-blue-600 focus:ring-2 focus:ring-blue-400 transition disabled:bg-blue-600 disabled:cursor-not-allowed"
              >
                Ajouter
              </button>
            </form>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Addnewuser;
